  "Google API keys": { es: "Claves de API de Google", ar: "مفاتيح Google API", zh: "Google API 密钥", sw: "Funguo za Google API", sv: "Google API-nycklar", de: "Google-API-Schlüssel", pt: "Chaves de API do Google", fr: "Clés API Google" },
